import os
import json

CONFIG_PATH = 'config.json'

def load_config():
    if not os.path.exists(CONFIG_PATH):
        return {}
    with open(CONFIG_PATH) as f:
        return json.loads(f.read())

def save_config(cfg):
    with open(CONFIG_PATH, 'w') as f:
        f.write(json.dumps(cfg, indent=2))

class Service:
    def __init__(self, name):
        self.name = name
        self.handlers = {}

    def register(self, key, fn):
        self.handlers[key] = fn

    def dispatch(self, key, payload):
        fn = self.handlers.get(key)
        if fn is None:
            print('no handler', key)
            return None
        return fn(payload)

def main():
    svc = Service('demo')
    svc.register('ping', lambda p: {'pong': p})
    print(svc.dispatch('ping', 1))

